declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);$config=require __DIR__.'/../config/database.php';$pdo=new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$st=$pdo->query("SELECT a.id,a.nombre_completo FROM alumnos a INNER JOIN sedes s ON s.id=a.sede_id WHERE s.clave='MONTEVERDE' ORDER BY a.nombre_completo");$alumnos=$st->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conciliación PROA — Hache Natación</title><style>
:root{--ink:#172033;--muted:#64748b;--line:#e2e8f0;--paper:#fff;--bg:#f3f6fa;--ok:#166534;--okbg:#ecfdf3;--warn:#92400e;--warnbg:#fff7ed;--bad:#991b1b;--badbg:#fff1f2;--blue:#1d4ed8;--bluebg:#eff6ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,Manrope,system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink)}.wrap{max-width:1120px;margin:auto;padding:28px 14px 42px}.ey{font-size:10px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#567089}h1{margin:5px 0 6px;font-size:29px}.sub{color:var(--muted);font-size:14px;line-height:1.5;margin-bottom:16px}.toolbar,.card,.panel,.status,.fold{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 8px 28px rgba(15,23,42,.035)}.toolbar{padding:12px 14px;display:flex;gap:12px;align-items:center;justify-content:space-between;margin-bottom:11px}.toolbar input,.field input,.field select,.form button{min-height:43px;border:1px solid #cbd5e1;border-radius:10px;padding:9px 10px;font:inherit}.toolbar small{color:var(--muted)}.status{padding:17px;margin-bottom:11px;display:flex;align-items:center;justify-content:space-between;gap:12px}.status strong{display:block;font-size:25px}.status span{font-size:12px;color:var(--muted)}.status.ok{background:linear-gradient(135deg,#fff,#f0fdf4);border-color:#bbf7d0}.status.warn{background:linear-gradient(135deg,#fff,#fff7ed);border-color:#fed7aa}.status.bad{background:linear-gradient(135deg,#fff,#fff1f2);border-color:#fecdd3}.badge{padding:8px 11px;border-radius:999px;font-size:10px!important;font-weight:900;text-transform:uppercase}.ok .badge{background:var(--okbg);color:var(--ok)!important}.warn .badge{background:var(--warnbg);color:var(--warn)!important}.bad .badge{background:var(--badbg);color:var(--bad)!important}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-bottom:11px}.card{padding:14px}.card .k{font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.card .v{font-size:21px;font-weight:900;margin-top:5px}.card .n{font-size:10px;color:var(--muted);margin-top:3px;line-height:1.35}.panel{padding:16px;margin-bottom:11px}.fold{margin-bottom:11px;overflow:visible}.fold>summary{list-style:none;cursor:pointer;padding:15px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;font-weight:900}.fold>summary::-webkit-details-marker{display:none}.fold>summary::after{content:'⌄';font-size:20px;color:var(--muted);transition:transform .2s}.fold[open]>summary::after{transform:rotate(180deg)}.fold-title{display:flex;align-items:center;gap:10px}.fold-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#eef3f7;font-size:17px}.fold.primary-fold{border-color:#bfd3e3}.fold.primary-fold>summary{background:linear-gradient(135deg,#f8fbfd,#fff)}.fold.primary-fold .fold-icon{background:#123b5d;color:#fff}.fold-body{padding:0 16px 16px}.fold-hint{font-size:11px;color:var(--muted);font-weight:600}.section-head{display:flex;align-items:end;justify-content:space-between;gap:12px;margin-bottom:12px}.section-head h2{margin:3px 0 0;font-size:18px}.formula{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.formula>div{background:#f8fafc;border:1px solid var(--line);border-radius:12px;padding:12px}.formula b{display:block;font-size:15px;margin-top:4px}.formula small{color:var(--muted)}.equation{margin-top:9px;padding:12px;border-radius:12px;background:#172033;color:#fff;font-size:12px;line-height:1.5}.auto-note{background:var(--bluebg);border:1px solid #bfdbfe;color:#1e3a8a;padding:11px 12px;border-radius:11px;font-size:12px;margin-bottom:10px}.form{display:grid;grid-template-columns:1.2fr .65fr .8fr 1.25fr 1fr;gap:8px;align-items:end}.field{display:grid;gap:5px;position:relative}.field label{font-size:9px;text-transform:uppercase;font-weight:900;color:var(--muted)}.form button{border:0;background:var(--ink);color:#fff;font-weight:850;cursor:pointer}.student-results{display:none;position:absolute;z-index:20;top:100%;left:0;right:0;max-height:230px;overflow:auto;background:#fff;border:1px solid #cbd5e1;border-radius:10px;box-shadow:0 12px 30px rgba(15,23,42,.16)}.student-results.show{display:block}.student-results button{display:block;width:100%;min-height:0;border:0;border-bottom:1px solid #eef2f7;border-radius:0;background:#fff;color:var(--ink);padding:10px;text-align:left;font-weight:700}.student-results button:last-child{border-bottom:0}.selected-student{font-size:10px;color:var(--ok);min-height:13px}.msg{min-height:18px;margin-top:7px;font-size:12px;font-weight:750}.msg.good{color:var(--ok)}.msg.bad{color:var(--bad)}.list{display:grid;gap:7px}.row{display:grid;grid-template-columns:.7fr 1.25fr .7fr 1.1fr 1.3fr .55fr;gap:8px;align-items:center;padding:10px 11px;border:1px solid var(--line);border-radius:11px;font-size:12px}.row.head{background:#f8fafc;border:0;color:var(--muted);font-size:9px;font-weight:900;text-transform:uppercase}.row.auto{background:#f8fbff;border-color:#dbeafe}.row.void{opacity:.55}.money{font-weight:900}.impact.plus{color:var(--warn)}.impact.minus{color:var(--ok)}.autotag,.voidtag{display:inline-block;padding:4px 7px;border-radius:999px;font-size:9px;font-weight:900}.autotag{background:var(--bluebg);color:var(--blue)}.voidtag{background:var(--badbg);color:var(--bad)}.annul{border:0;background:var(--badbg);color:var(--bad);padding:7px 8px;border-radius:8px;font-weight:850;cursor:pointer}.empty{padding:18px;text-align:center;border:1px dashed #cbd5e1;border-radius:11px;color:var(--muted);font-size:12px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.cards .card:first-child{grid-column:1/-1}.form{grid-template-columns:1fr 1fr}.row.head{display:none}.row{grid-template-columns:1fr 1fr}.row>div::before{content:attr(data-label);display:block;font-size:8px;text-transform:uppercase;color:var(--muted);font-weight:900;margin-bottom:2px}.row>div:nth-child(2),.row>div:nth-child(5){grid-column:1/-1}.formula{grid-template-columns:1fr}.toolbar,.status{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.wrap{padding:18px 10px 32px}.cards{grid-template-columns:1fr 1fr}.card .v{font-size:18px}.form{grid-template-columns:1fr}h1{font-size:25px}.fold>summary{padding:13px 14px}.fold-body{padding:0 14px 14px}}
</style></head><body><main class="wrap"><div class="ey">Finanzas · Monteverde · ADMIN</div><h1>Conciliación PROA</h1><div class="sub">Cuenta corriente entre Hache Natación y PROA. La obligación y las comisiones salen de los registros oficiales; tú solo capturas el dinero realmente entregado o recibido directamente por PROA.</div><div class="toolbar"><div><b>Periodo</b><br><small>La conciliación se calcula por mes.</small></div><input id="periodo" type="month"></div><div id="status" class="status"></div><div class="cards"><div class="card"><div class="k">Obligación PROA</div><div class="v" id="obligacion">$0</div><div class="n">50% mensualidades + 50% intensivos + 100% inscripciones.</div></div><div class="card"><div class="k">Entregado a PROA</div><div class="v" id="entregado">$0</div><div class="n">Efectivo + transferencias.</div></div><div class="card"><div class="k">Pagos directos en PROA</div><div class="v" id="directos">$0</div><div class="n">Pagos de alumnos recibidos por PROA.</div></div><div class="card"><div class="k">Comisiones automáticas</div><div class="v" id="comisiones">$0</div><div class="n">Se toman de Comisiones PROA y reducen lo pendiente por entregar.</div></div><div class="card"><div class="k">Saldo</div><div class="v" id="saldo">$0</div><div class="n">Positivo: Hache debe. Negativo: PROA debe.</div></div></div>
<details id="movementFold" class="fold primary-fold" open><summary><div class="fold-title"><span class="fold-icon">＋</span><div><div>Registrar movimiento</div><div class="fold-hint">Efectivo · transferencia · pago directo de alumno a PROA</div></div></div></summary><div class="fold-body"><div class="form"><div class="field"><label>Tipo</label><select id="tipo"><option value="PAGO_DIRECTO_PROA">Alumno pagó directamente en PROA</option><option value="EFECTIVO_A_PROA">Entregué efectivo a PROA</option><option value="TRANSFERENCIA_A_PROA">Hice transferencia a PROA</option></select></div><div class="field"><label>Importe</label><input id="importe" type="number" min="0.01" step="0.01" placeholder="0.00"></div><div class="field"><label>Fecha</label><input id="fecha" type="datetime-local"></div><div class="field"><label id="alumnoLabel">Alumno que pagó</label><input id="alumno" autocomplete="off" placeholder="Buscar alumno…"><input id="alumnoId" type="hidden"><div id="selectedStudent" class="selected-student"></div><div id="studentResults" class="student-results"></div></div><div class="field"><label>Observación</label><input id="obs" placeholder="Opcional"></div><button id="guardar">Registrar</button></div><div id="msg" class="msg"></div></div></details>
<details class="fold"><summary><div class="fold-title"><span class="fold-icon">∑</span><div><div>Cómo se forma la obligación</div><div class="fold-hint">Matriz automática del periodo</div></div></div></summary><div class="fold-body"><div class="formula"><div><small>Mensualidades cobradas</small><b id="mens">$0 × 50% = $0</b></div><div><small>Intensivos cobrados</small><b id="int">$0 × 50% = $0</b></div><div><small>Inscripciones cobradas</small><b id="ins">$0 × 100% = $0</b></div></div><div class="equation">SALDO = obligación PROA − comisiones automáticas a favor de Hache − efectivo/transferencias entregadas a PROA − pagos de alumnos recibidos directamente por PROA.</div></div></details>
<details class="fold"><summary><div class="fold-title"><span class="fold-icon">◆</span><div><div>Comisiones PROA del periodo</div><div class="fold-hint"><span id="autoCount">0 comisiones</span> · automáticas</div></div></div></summary><div class="fold-body"><div class="auto-note">Estos registros vienen directamente del módulo Comisiones PROA. Si cambias una comisión allí, la conciliación se actualiza sola.</div><div id="autoRows" class="list"></div></div></details>
<section class="panel"><div class="section-head"><div><div class="ey">Auditoría</div><h2>Movimientos manuales del periodo</h2></div><span id="count"></span></div><div id="rows" class="list"></div></section></main><script>
const students=<?=json_encode($alumnos,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const $=id=>document.getElementById(id),money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:0,maximumFractionDigits:2}),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const labels={EFECTIVO_A_PROA:'Efectivo a PROA',TRANSFERENCIA_A_PROA:'Transferencia a PROA',PAGO_DIRECTO_PROA:'Pago directo en PROA',COMISION_RECIBIDA_PROA:'Comisión manual antigua (sin impacto)'};function localNow(){const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}function flash(t,c=''){$('msg').textContent=t;$('msg').className='msg '+c}function clearStudent(){$('alumnoId').value='';$('selectedStudent').textContent=''}function chooseStudent(id,name){$('alumnoId').value=id;$('alumno').value=name;$('selectedStudent').textContent='✓ Alumno seleccionado';$('studentResults').classList.remove('show')}function searchStudents(){clearStudent();const q=$('alumno').value.trim().toLocaleLowerCase('es');if($('tipo').value!=='PAGO_DIRECTO_PROA'||q.length<1){$('studentResults').classList.remove('show');return}const found=students.filter(s=>s.nombre_completo.toLocaleLowerCase('es').includes(q)).slice(0,12);$('studentResults').innerHTML=found.length?found.map(s=>`<button type="button" data-id="${esc(s.id)}" data-name="${esc(s.nombre_completo)}">${esc(s.nombre_completo)}</button>`).join(''):'<div style="padding:10px;color:#64748b;font-size:12px">No hay alumnos que coincidan.</div>';$('studentResults').classList.add('show');$('studentResults').querySelectorAll('button').forEach(b=>b.onclick=()=>chooseStudent(b.dataset.id,b.dataset.name))}$('alumno').addEventListener('input',searchStudents);$('alumno').addEventListener('focus',searchStudents);document.addEventListener('click',e=>{if(!e.target.closest('#alumno')&&!e.target.closest('#studentResults'))$('studentResults').classList.remove('show')});function syncForm(){const direct=$('tipo').value==='PAGO_DIRECTO_PROA';$('alumnoLabel').textContent=direct?'Alumno que pagó':'Referencia / persona';$('alumno').placeholder=direct?'Buscar alumno…':'Opcional';if(!direct){clearStudent();$('studentResults').classList.remove('show')}}$('tipo').onchange=syncForm;$('periodo').value=new Date().toISOString().slice(0,7);$('fecha').value=localNow();syncForm();let autoFoldClosed=false;addEventListener('scroll',()=>{const f=$('movementFold');if(!f)return;if(scrollY>220&&f.open&&!autoFoldClosed){f.open=false;autoFoldClosed=true}},{passive:true});$('movementFold').addEventListener('toggle',()=>{if($('movementFold').open)autoFoldClosed=true});async function load(){flash('');try{const r=await fetch('/api/conciliacion-proa.php?periodo='+encodeURIComponent($('periodo').value),{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo cargar');const b=d.base,x=d.resumen,a=d.comisiones_automaticas||[];$('obligacion').textContent=money(b.total_proa);$('entregado').textContent=money(x.entregado_a_proa);$('directos').textContent=money(x.pagos_directos_proa);$('comisiones').textContent=money(x.comisiones_recibidas);$('saldo').textContent=money(x.saldo);$('mens').textContent=`${money(b.mensualidades)} × 50% = ${money(b.proa_mensualidades)}`;$('int').textContent=`${money(b.intensivos)} × 50% = ${money(b.proa_intensivos)}`;$('ins').textContent=`${money(b.inscripciones)} × 100% = ${money(b.proa_inscripciones)}`;const st=$('status');if(x.situacion==='CUADRADO'){st.className='status ok';st.innerHTML=`<div><strong>Conciliado · ${money(0)}</strong><span>Este periodo está cuadrado con PROA.</span></div><span class="badge">En cero ✓</span>`}else if(x.situacion==='HACHE_DEBE_PROA'){st.className='status warn';st.innerHTML=`<div><strong>Hache debe ${money(x.saldo)}</strong><span>Fondo pendiente por entregar a PROA.</span></div><span class="badge">Pendiente</span>`}else{st.className='status bad';st.innerHTML=`<div><strong>PROA debe ${money(Math.abs(x.saldo))}</strong><span>El balance está a favor de Hache Natación.</span></div><span class="badge">A favor de Hache</span>`}$('autoCount').textContent=`${a.length} comisión${a.length===1?'':'es'}`;$('autoRows').innerHTML=a.length?a.map(c=>`<div class="row auto"><div data-label="Fecha">${esc(new Date(String(c.created_at).replace(' ','T')).toLocaleDateString('es-MX',{day:'2-digit',month:'short'}))}</div><div data-label="Movimiento"><b>Comisión PROA</b> <span class="autotag">AUTOMÁTICA</span></div><div class="money" data-label="Importe">${money(c.importe)}</div><div class="money impact minus" data-label="Impacto">−${money(c.importe)}</div><div data-label="Detalle">${esc(c.alumno_proa_nombre)}${c.observacion?' · '+esc(c.observacion):''}</div><div></div></div>`).join(''):`<div class="empty">No hay comisiones PROA registradas para este periodo.</div>`;$('count').textContent=`${d.movimientos.length} movimiento${d.movimientos.length===1?'':'s'}`;$('rows').innerHTML=d.movimientos.length?d.movimientos.map(m=>{const active=m.estado==='ACTIVO',impact=Number(m.impacto||0),detail=[m.alumno_nombre,m.referencia,m.observacion].filter(Boolean).join(' · ')||'—';return `<div class="row ${active?'':'void'}"><div data-label="Fecha">${esc(new Date(String(m.fecha).replace(' ','T')).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}))}</div><div data-label="Movimiento"><b>${esc(labels[m.tipo]||m.tipo)}</b>${active?'':' <span class="voidtag">ANULADO</span>'}</div><div class="money" data-label="Importe">${money(m.importe)}</div><div class="money impact ${impact>0?'plus':'minus'}" data-label="Impacto">${active?(impact>0?'+':'−')+money(Math.abs(impact)):'$0'}</div><div data-label="Detalle">${esc(detail)}${!active&&m.motivo_anulacion?`<br><small>Anulado: ${esc(m.motivo_anulacion)}</small>`:''}</div><div data-label="Acción">${active?`<button class="annul" data-id="${esc(m.id)}">Anular</button>`:''}</div></div>`}).join(''):`<div class="empty">Aún no hay movimientos manuales en este periodo.</div>`}catch(e){$('status').className='status bad';$('status').innerHTML=`<div><strong>No se pudo cargar</strong><span>${esc(e.message||'Error')}</span></div><span class="badge">Error</span>`}}$('periodo').onchange=load;$('guardar').onclick=async()=>{flash('');const direct=$('tipo').value==='PAGO_DIRECTO_PROA';if(direct&&!$('alumnoId').value){flash('Busca y selecciona un alumno de la lista.','bad');$('alumno').focus();return}const body={tipo:$('tipo').value,importe:Number($('importe').value||0),fecha:$('fecha').value,observacion:$('obs').value.trim()};if(direct){body.alumno_id=$('alumnoId').value;body.alumno_nombre=$('alumno').value}else body.referencia=$('alumno').value.trim();try{const r=await fetch('/api/conciliacion-proa.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo registrar');$('importe').value='';$('alumno').value='';clearStudent();$('obs').value='';$('fecha').value=localNow();flash('Movimiento registrado.','good');await load()}catch(e){flash(e.message||'No se pudo registrar','bad')}};$('rows').onclick=async e=>{const b=e.target.closest('[data-id]');if(!b)return;const motivo=prompt('Motivo de la anulación:');if(!motivo||!motivo.trim())return;try{const r=await fetch('/api/conciliacion-proa.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'ANULAR',id:b.dataset.id,motivo:motivo.trim()})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo anular');await load()}catch(e){flash(e.message||'No se pudo anular','bad')}};load();
</script></body></html>